<?php require_once 'config/app.php';$count=$conn->query("SELECT COUNT(*) c FROM users WHERE role='admin'")->fetch_assoc()['c'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST' && !$count){$name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password'];if(strlen($pass)<8)$msg='Password must be at least 8 characters.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=stmt($conn,'INSERT INTO users(full_name,email,password,role) VALUES(?,?,?,\'admin\')','sss',[$name,$email,$hash]);redirect('login.php?admin_created=1');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin setup</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><div class="auth-side"><div class="auth-brand">Auto<span>Care</span></div><h1>Set up your<br>workspace.</h1><p>Create the first administrator account to manage your AutoCare service system.</p></div><div class="auth-box"><form class="auth-card" method="post"><h2>Administrator setup</h2><p><?= $count?'An administrator already exists. Delete this setup file.':'Create your first admin account.' ?></p><?php if($msg):?><div class="alert error"><?=e($msg)?></div><?php endif;?><?php if(!$count):?><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required></div><button class="btn">Create administrator</button><?php else:?><a class="btn" href="login.php">Go to login</a><?php endif;?></form></div></body></html>
